"use client";

import { useEffect, useState } from "react";
import { Plus_Jakarta_Sans } from "next/font/google";
import styles from "./CinematicHero.module.css";

const plusJakartaSans = Plus_Jakarta_Sans({
  subsets: ["latin"],
  weight: ["400", "600", "800"],
});

const sequence = [
  "Boring websites?",
  "Let’s make them unforgettable.",
  "Websites that represent your brand.",
  "Web apps that power your business.",
  "Mobile apps that keep you connected.",
  "Branding that makes people remember you.",
  "We discuss. We design. We build.",
  "Everything your brand needs to grow.",
];

export default function CinematicHero() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showCTA, setShowCTA] = useState(false);
  const [isEntered, setIsEntered] = useState(false);
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    // Only lock scrolling if we haven't entered yet
    if (!isEntered && !isExiting) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }

    return () => {
      document.body.style.overflow = "";
    };
  }, [isEntered, isExiting]);

  useEffect(() => {
    if (currentIndex < sequence.length - 1) {
      const timer = setTimeout(() => {
        setCurrentIndex((prev) => prev + 1);
      }, 3500); // 3.5s per line
      return () => clearTimeout(timer);
    } else {
      const ctaTimer = setTimeout(() => {
        setShowCTA(true);
      }, 1000); // Wait 1s after last text appears to show CTA
      return () => clearTimeout(ctaTimer);
    }
  }, [currentIndex]);

  const handleEnter = () => {
    setIsExiting(true);
    setTimeout(() => {
      setIsEntered(true);
    }, 1000); // Wait for exit animation to complete
  };

  if (isEntered) return null;

  return (
    <section className={`${styles.heroRoot} ${isExiting ? styles.exiting : ""} ${plusJakartaSans.className}`}>
      <div className={styles.heroContent}>
        {sequence.map((text, idx) => (
          <h1
            key={idx}
            className={`${styles.heroText} ${
              idx === currentIndex ? styles.active : ""
            } ${idx < currentIndex ? styles.previous : ""} ${plusJakartaSans.className}`}
            aria-hidden={idx !== currentIndex}
          >
            {text}
          </h1>
        ))}
        
        <div className={`${styles.ctaWrapper} ${showCTA ? styles.ctaActive : ""}`}>
          <button onClick={handleEnter} className={`${styles.ctaButton} ${plusJakartaSans.className}`}>
            Start Our Branding Story &rarr;
          </button>
        </div>
      </div>
    </section>
  );
}
